    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        // Arrange
        _sut.CreateOrder("cust-A", CreateItems());
        _sut.CreateOrder("cust-A", CreateItems(2));
        _sut.CreateOrder("cust-B", CreateItems());

        // Act
        var orders = _sut.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var orders = _sut.GetOrdersByCustomer("unknown");

        // Assert
        Assert.IsEmpty(orders);
    }

    [TestMethod]
    [DataRow(1, 10, 1, 10)]
    [DataRow(2, 5, 3, 30)]
    [DataRow(1, 99.99, 1, 99.99)]
    public void CreateOrder_CalculatesTotalCorrectly(
